// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        // Admissible domain: any plain externally-owned caller (no code).
        // For every such caller, the reference reverts because the
        // supportsToken check performs an external call to msg.sender,
        // which cannot be satisfied by an EOA.
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(this));

        vm.prank(actor);
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a codeless caller can never receive the airdrop;
        // the call reverts and its balance stays 0.
        assertTrue(!ok && c.tokenBalance(actor) == 0);
    }
}
